using System.Text.Json;
using FamilyVeda.Application.Agents;
using FamilyVeda.Application.Triage;
using FamilyVeda.Domain.Common;
using FamilyVeda.Domain.Identity;
using FamilyVeda.Domain.Safety;
using FamilyVeda.Domain.Triage;
using FamilyVeda.Infrastructure.Persistence;
using FamilyVeda.Infrastructure.Triage;
using FluentAssertions;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Configuration;

namespace FamilyVeda.UnitTests;

public sealed class TriageOrchestratorNoDataTests
{
    [Fact]
    public async Task NoDataAgent_IsExcludedFromConfidenceCheck()
    {
        var (db, triageCase) = await SeedAsync();
        await Run(db, triageCase, (AgentKind.Context, 0.8m, true), (AgentKind.Analysis, 0.9m, true), (AgentKind.FamilialRisk, 0m, false));

        triageCase.Status.Should().Be(TriageStatus.PendingDoctorReview);
        var noData = await db.AgentTraces.SingleAsync(x => x.Agent == AgentKind.FamilialRisk);
        noData.Status.Should().Be(AgentStepStatus.NoData);
        noData.Confidence.Should().Be(0m);
        noData.OutputSchemaValid.Should().BeTrue();
        (await db.AgentTraces.SingleAsync(x => x.Agent == AgentKind.SafetyValidation)).Confidence.Should().Be(0.8m);
    }

    [Fact]
    public async Task AllAgentsNoData_DoesNotPassSilently_StaysLowConfidence()
    {
        var (db, triageCase) = await SeedAsync();
        await Run(db, triageCase, (AgentKind.Context, 0m, false), (AgentKind.Analysis, 0m, false), (AgentKind.FamilialRisk, 0m, false));

        triageCase.Status.Should().Be(TriageStatus.LowConfidence);
        triageCase.FailureCode.Should().Be("LOW_CONFIDENCE");
        triageCase.DraftAdvisoryJson.Should().BeNull();
    }

    [Fact]
    public async Task AgentWithDataBelowThreshold_Fails()
    {
        var (db, triageCase) = await SeedAsync();
        await Run(db, triageCase, (AgentKind.Context, 0.9m, true), (AgentKind.Analysis, 0.5m, true), (AgentKind.FamilialRisk, 0m, false));

        triageCase.Status.Should().Be(TriageStatus.LowConfidence);
    }

    [Fact]
    public void MarkNoDataIfEmpty_ForcesZeroConfidence()
    {
        var result = new AgentRunResult(AgentKind.Analysis, "{}", 0.41m, [], [], [], true);
        var marked = AgentInputData.MarkNoDataIfEmpty(result, hasData: false);
        marked.Confidence.Should().Be(0m);
        marked.HasData.Should().BeFalse();
        AgentInputData.HasAny(Array.Empty<int>()).Should().BeFalse();
        AgentInputData.HasAny(new[] { 1 }).Should().BeTrue();
        AgentInputData.HasAny(new[] { 1 }, minimumCount: 2).Should().BeFalse();
    }

    private static async Task Run(AppDbContext db, TriageCase triageCase, params (AgentKind Kind, decimal Confidence, bool HasData)[] agents)
    {
        var stubs = agents.Select(a => (IAgent)new StubAgent(a.Kind, a.Confidence, a.HasData)).ToList();
        var orchestrator = new TriageOrchestrator(db, stubs, new SafetyValidationService(), new StubNotifications(), new ConfigurationBuilder().Build());
        await orchestrator.RunAsync(triageCase.Id, CancellationToken.None);
    }

    private static async Task<(AppDbContext, TriageCase)> SeedAsync()
    {
        var options = new DbContextOptionsBuilder<AppDbContext>().UseInMemoryDatabase(Guid.NewGuid().ToString()).Options;
        var db = new AppDbContext(options);
        var user = new UserAccount { Email = "synthetic-nodata@example.invalid", PasswordHash = "synthetic", DisplayName = "Synthetic User", UserType = UserType.FamilyUser };
        var family = new Family { Name = "Synthetic Family", CreatedByUser = user };
        var member = new Member { Family = family, User = user, DisplayName = "Synthetic Member", DateOfBirth = new DateOnly(1990, 1, 1), Role = FamilyRole.Head };
        var episode = new Episode { Member = member, SymptomsJson = JsonSerializer.Serialize(new[] { "cough" }), DurationDays = 1, Severity = 2 };
        var triageCase = new TriageCase { Episode = episode, Member = member, Status = TriageStatus.Planning };
        db.Add(triageCase);
        await db.SaveChangesAsync();
        return (db, triageCase);
    }

    private sealed class StubAgent(AgentKind kind, decimal confidence, bool hasData) : IAgent
    {
        public AgentKind Kind => kind;
        public Task<AgentRunResult> RunAsync(AgentRunContext context, CancellationToken cancellationToken) =>
            Task.FromResult(new AgentRunResult(kind, "{}", confidence, [], [], [], true, HasData: hasData));
    }

    private sealed class StubNotifications : INotificationService
    {
        public Task<NotificationSubscriptionDto> SubscribeAsync(NotificationSubscriptionRequest request, CancellationToken cancellationToken) => throw new NotSupportedException();
        public Task SendCaseStatusAsync(Guid caseId, TriageStatus status, CancellationToken cancellationToken) => Task.CompletedTask;
        public Task<FamilyVeda.Application.Common.PagedResult<NotificationDto>> GetInboxAsync(int page, int pageSize, CancellationToken cancellationToken) => throw new NotSupportedException();
    }
}
